## Java Implementation

### Iterative Version (recommended)

```java
public class BinarySearch {

    public static int binarySearch(int[] arr, int target) {
        int left = 0;
        int right = arr.length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;  // avoids integer overflow

            if (arr[mid] == target) {
                return mid;
            } else if (arr[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return -1;  // target not found
    }

    public static void main(String[] args) {
        int[] numbers = {2, 5, 8, 12, 16, 23, 38, 45, 56, 72};
        int result = binarySearch(numbers, 23);
        System.out.println("Found at index: " + result);  // Found at index: 5

        result = binarySearch(numbers, 1);
        System.out.println("Found at index: " + result);  // Found at index: -1
    }
}
```

### Recursive Version

```java
public class BinarySearchRecursive {

    public static int binarySearch(int[] arr, int left, int right, int target) {
        if (left > right) {
            return -1;
        }

        int mid = left + (right - left) / 2;

        if (arr[mid] == target) {
            return mid;
        } else if (arr[mid] < target) {
            return binarySearch(arr, mid + 1, right, target);
        } else {
            return binarySearch(arr, left, mid - 1, target);
        }
    }

    public static void main(String[] args) {
        int[] numbers = {2, 5, 8, 12, 16, 23, 38, 45, 56, 72};
        int result = binarySearch(numbers, 0, numbers.length - 1, 23);
        System.out.println("Found at index: " + result);  // Found at index: 5
    }
}
```

